<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$client=(int)($_GET['client_id']??$_POST['client_id']??0);$project=(int)($_GET['project_id']??$_POST['project_id']??0);$proposal=(int)($_GET['proposal_id']??$_POST['proposal_id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){$items=[];$descs=$_POST['description']??[];$qtys=$_POST['quantity']??[];$prices=$_POST['unit_price']??[];foreach($descs as $i=>$desc){$desc=trim((string)$desc);$q=(float)($qtys[$i]??1);$price=(float)($prices[$i]??0);if($desc!==''&&$q>0)$items[]=[$desc,$q,$price,round($q*$price,2)];}if(!$client||!$items)exit('Client and at least one invoice item are required.');$subtotal=array_sum(array_column($items,3));$taxRate=(float)($_POST['tax_rate']??0);$tax=round($subtotal*$taxRate/100,2);$total=$subtotal+$tax;$num='INV-'.date('Y').'-'.str_pad((string)((int)$db->query('SELECT COUNT(*) FROM invoices')->fetchColumn()+1),5,'0',STR_PAD_LEFT);$q=$db->prepare('INSERT INTO invoices(client_id,project_id,proposal_id,invoice_number,issue_date,due_date,status,currency,subtotal,tax_rate,tax_amount,total,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$client,$project?:null,$proposal?:null,$num,$_POST['issue_date']?:date('Y-m-d'),$_POST['due_date']?:null,'draft',$_POST['currency']?:'USD',$subtotal,$taxRate,$tax,$total,trim($_POST['notes']??'')]);$invoiceId=(int)$db->lastInsertId();$qi=$db->prepare('INSERT INTO invoice_items(invoice_id,description,quantity,unit_price,line_total,sort_order) VALUES(?,?,?,?,?,?)');foreach($items as $i=>$it)$qi->execute([$invoiceId,$it[0],$it[1],$it[2],$it[3],$i]);header('Location: invoice-view.php?id='.$invoiceId);exit;}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>New Invoice</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="card"><div class="card-body"><h1 class="h4">Create Invoice</h1><form method="post"><input type="hidden" name="client_id" value="<?=$client?>"><input type="hidden" name="project_id" value="<?=$project?>"><input type="hidden" name="proposal_id" value="<?=$proposal?>"><div class="row g-2 mb-3"><div class="col-md-4"><label>Issue date</label><input class="form-control" type="date" name="issue_date" value="<?=date('Y-m-d')?>"></div><div class="col-md-4"><label>Due date</label><input class="form-control" type="date" name="due_date"></div><div class="col-md-4"><label>Currency</label><input class="form-control" name="currency" value="USD"></div></div><h2 class="h6">Items</h2><div id="items"><div class="row g-2 mb-2 item"><div class="col-md-6"><input class="form-control" name="description[]" placeholder="Description" required></div><div class="col-md-2"><input class="form-control" type="number" step="0.01" name="quantity[]" value="1"></div><div class="col-md-3"><input class="form-control" type="number" step="0.01" name="unit_price[]" value="0"></div></div></div><button class="btn btn-outline-secondary mb-3" type="button" onclick="items.insertAdjacentHTML('beforeend',document.querySelector('.item').outerHTML)">Add item</button><div class="row"><div class="col-md-3"><label>Tax %</label><input class="form-control" type="number" step="0.001" name="tax_rate" value="0"></div></div><textarea class="form-control my-3" name="notes" placeholder="Notes"></textarea><button class="btn btn-dark">Create Invoice</button></form></div></div></main></body></html>